/// The mouth is the rig's only shape swap.
enum PinchMouth: Int, CaseIterable, Sendable { case smile, flat, open, `o` }

/// One frame of Pinch: every rig.json param at its value. `PinchPose()` is the rest pose.
struct PinchPose: Equatable, Sendable {
    /// pinch-root scale about the feet [80,148]; scaleX = 1/sqrt(scaleY) (scaleY, 0.85…1.15)
    var bodySquash: Double = 1
    /// pinch-root translateY (hops: ease-out up, ease-in down) (px, -24…8)
    var bodyY: Double = 0
    /// pinch-root rotate about the feet; lookX adds a 2 deg lean (deg, -12…12)
    var tilt: Double = 0
    /// arm-l rotate about the shoulder (+ raises); claw-l counter-rotates -0.8x so it stays upright (deg, -40…45)
    var clawL: Double = 0
    /// arm-r rotate about the shoulder (+ raises, mirrored sign); claw-r counter-rotates -0.8x (deg, -40…86)
    var clawR: Double = 0
    /// extra claw-l rotate about the wrist (+ turns the crusher in toward the face: thinking, clap) (deg, -60…140)
    var wristL: Double = 0
    /// extra claw-r rotate about the wrist, mirrored sense (deg, -60…140)
    var wristR: Double = 0
    /// both claws: -1 wide open, 0 rest gap, 1 jaws meet (close_deg) (0..1, -1…1)
    var pinch: Double = 0
    /// crusher only, added to pinch and clamped (0..1, -1…1)
    var pinchL: Double = 0
    /// cutter only (grips the lens handle), added to pinch and clamped (0..1, -1…1)
    var pinchR: Double = 0
    /// both lids: coverage = 1 - eyeOpen; above 1 the eyes scale up (surprise 1.15) (0..1.3, 0…1.3)
    var eyeOpen: Double = 1
    /// extra lid coverage on eye-l, combined 1-(1-a)(1-b) with eyeOpen (sideeye dry lid 0.4) (0..1, 0…1)
    var lidL: Double = 0
    /// extra lid coverage on eye-r (0..1, 0…1)
    var lidR: Double = 0
    /// lid-l tilt: + kind (outer corner down), - dry; never a frown (deg, -8…14)
    var browL: Double = 0
    /// lid-r tilt, same sense mirrored (deg, -8…14)
    var browR: Double = 0
    /// crossfade the eyes to happy closed ^ ^ arcs (celebrate) (0..1, 0…1)
    var joy: Double = 0
    /// eye-l/eye-r translateX +-3.5 (lids ride along), body lean 2 deg (-1..1, -1…1)
    var lookX: Double = 0
    /// eye-l/eye-r translateY +-2.5 (-1..1, -1…1)
    var lookY: Double = 0
    /// the only shape swap: smile | flat | open | o (step)
    var mouth: PinchMouth = .smile
    /// smile height (0 = flat line, 1 = rest smile); clamped at -0.2, never a frown (scaleY, -0.2…1.4)
    var mouthCurve: Double = 1
    /// mouth rotate about its centre (half smile) (deg, -14…14)
    var mouthTilt: Double = 0
    /// blush opacity (pinch-blush already carries its alpha) (0..1, 0…1)
    var blush: Double = 0
    /// both antennae rotate the same way (right one x0.85) (deg, -16…16)
    var antennaSway: Double = 0
    /// antennae perk up (+) or droop (-), mirrored (deg, -16…24)
    var antennaLift: Double = 0
    /// sparkle opacity and burst scale 0.72 -> 1.06 (0..1, 0…1)
    var sparkle: Double = 0
    /// sweat drop opacity, slides 3.5 px down as it appears (0..1, 0…1)
    var sweat: Double = 0
    /// z opacity; the three z's drift on a 2400 ms cycle of engine time (0..1, 0…1)
    var zzz: Double = 0
    /// 0 lowered in the cutter -> 1 glass on eye-r (IK macro on arm-r, claw-r, lens); lens-view shows the magnified eye from 0.72 (0..1, 0…1)
    var lens: Double = 0
    /// camera light: green wash in the glass + a ring outside the rim. Carries information: never animate it for decoration (0..1, 0…1)
    var lensGlow: Double = 0
    /// lens scale about the glass centre (the tap toward the viewer) (scale, 0.8…1.4)
    var lensZoom: Double = 1
    /// lens tucked away (opacity 0, scale 0.65 about the grip) so both claws can clap (0..1, 0…1)
    var lensOut: Double = 0
    /// one green glint sweeps across the glass, opacity sin(pi*glint) (connected) (0..1, 0…1)
    var glint: Double = 0
    /// paper slip in the crusher (reading) (0..1, 0…1)
    var paper: Double = 0
    /// the one allowed gradient, behind Pinch, celebrate only (0..1, 0…1)
    var bloom: Double = 0

    init() {}

    /// Read or write any param by key (mouth as its PinchMouth raw value).
    subscript(_ k: PinchParam) -> Double {
        get {
            switch k {
            case .bodySquash: return bodySquash
            case .bodyY: return bodyY
            case .tilt: return tilt
            case .clawL: return clawL
            case .clawR: return clawR
            case .wristL: return wristL
            case .wristR: return wristR
            case .pinch: return pinch
            case .pinchL: return pinchL
            case .pinchR: return pinchR
            case .eyeOpen: return eyeOpen
            case .lidL: return lidL
            case .lidR: return lidR
            case .browL: return browL
            case .browR: return browR
            case .joy: return joy
            case .lookX: return lookX
            case .lookY: return lookY
            case .mouth: return Double(mouth.rawValue)
            case .mouthCurve: return mouthCurve
            case .mouthTilt: return mouthTilt
            case .blush: return blush
            case .antennaSway: return antennaSway
            case .antennaLift: return antennaLift
            case .sparkle: return sparkle
            case .sweat: return sweat
            case .zzz: return zzz
            case .lens: return lens
            case .lensGlow: return lensGlow
            case .lensZoom: return lensZoom
            case .lensOut: return lensOut
            case .glint: return glint
            case .paper: return paper
            case .bloom: return bloom
            }
        }
        set {
            switch k {
            case .bodySquash: bodySquash = newValue
            case .bodyY: bodyY = newValue
            case .tilt: tilt = newValue
            case .clawL: clawL = newValue
            case .clawR: clawR = newValue
            case .wristL: wristL = newValue
            case .wristR: wristR = newValue
            case .pinch: pinch = newValue
            case .pinchL: pinchL = newValue
            case .pinchR: pinchR = newValue
            case .eyeOpen: eyeOpen = newValue
            case .lidL: lidL = newValue
            case .lidR: lidR = newValue
            case .browL: browL = newValue
            case .browR: browR = newValue
            case .joy: joy = newValue
            case .lookX: lookX = newValue
            case .lookY: lookY = newValue
            case .mouth: mouth = PinchMouth(rawValue: Int(newValue.rounded())) ?? .smile
            case .mouthCurve: mouthCurve = newValue
            case .mouthTilt: mouthTilt = newValue
            case .blush: blush = newValue
            case .antennaSway: antennaSway = newValue
            case .antennaLift: antennaLift = newValue
            case .sparkle: sparkle = newValue
            case .sweat: sweat = newValue
            case .zzz: zzz = newValue
            case .lens: lens = newValue
            case .lensGlow: lensGlow = newValue
            case .lensZoom: lensZoom = newValue
            case .lensOut: lensOut = newValue
            case .glint: glint = newValue
            case .paper: paper = newValue
            case .bloom: bloom = newValue
            }
        }
    }
}

/// clips.json easings by name (rig.js resolves a keyframe's easing name through this table).
extension PinchEase {
    static let out = PinchEase.bezier(0.23, 1, 0.32, 1)
    static let inOut = PinchEase.bezier(0.65, 0, 0.35, 1)
    static let sine = PinchEase.bezier(0.37, 0, 0.63, 1)
    static let anticip = PinchEase.bezier(0.5, 0, 0.75, 0)
    static let overshoot = PinchEase.bezier(0.2, 0.9, 0.3, 1.25)
    static let settle = PinchEase.spring(350, 0.4)
    static let snappy = PinchEase.spring(350, 0.15)
    static let smooth = PinchEase.spring(500, 0)
    static let celebrate = PinchEase.spring(600, 0.4)
}

